function projectSetup(){stop();active=null;view='projectSetup';shell.innerHTML=top('设计我的自主课题')+btn('← 返回探究实验室','home','quiet')+`<section class="v-card v-section"><h3>先确定研究方向，再写下自己的问题</h3><p class="v-muted">你可以在已有装置和物理模型范围内改变问题与方法。未实现的温度变化、非牛顿本构和容器壁面效应，暂不能作为本平台的实验变量。</p><div class="v-form"><div><label for="v5-kind">研究方向</label><select id="v5-kind"><option value="relation">研究变量之间的关系</option><option value="measure">测量一种未知流体的黏度</option><option value="optimize">在约束下优化管道流量</option><option value="compare">比较同一流体的测量方法</option></select></div><div id="v5-method-wrap"><label for="v5-method">主要装置</label><select id="v5-method"><option value="N">平行板装置</option><option value="P">毛细管装置</option><option value="S">落球装置</option></select></div>${field('我的研究问题','question','','例如：不同板间距下，应力与速度的关系是否相同？','input')}<div id="v5-project-help" class="v-note"></div><div><label for="v5-noise">读数模式</label><select id="v5-noise"><option value="instrument">合成读数误差 · 练习误差分析</option><option value="ideal">理想读数 · 观察模型关系</option></select></div></div><div class="v-actions">${btn('建立课题，查看任务卡 →','create','primary')}</div>${status()}</section>`;const update=()=>{const k=$('v5-kind').value;$('v5-method-wrap').hidden=['optimize','compare'].includes(k);$('v5-project-help').textContent={relation:'你可以选择当前装置支持的自变量与读数，定义控制条件，并保存方案修订。每轮单因素比较使用一份基准；新增一轮时保留此前数据。',measure:'流体黏度固定且隐藏。你选择装置、测量范围与分析关系；系统提供反演工具，结论仍需你解释。',optimize:'使用毛细管装置，自定目标倍率；允许同时改变半径、压差与管长。必须比较至少四种方案并满足 Re < 2000 的教学筛选条件。',compare:'同一份匿名流体，可从任意方法开始，至少完成两种方法的比较；每种方法至少三个不同条件，第三种方法可选。'}[k]};$('v5-kind').onchange=update;update();bindActions({home,create:()=>{const k=$('v5-kind').value,m=$('v5-method').value,question=$('v5-question').value.trim(),noise=$('v5-noise').value;if(question.length<6)throw Error('请把研究问题写具体一些，说明你想研究的量或比较的对象。');const id=k==='optimize'?'P4':k==='compare'?'C1':k==='measure'?{N:'N3',P:'P3',S:'S4'}[m]:{N:'N1',P:'P1',S:'S2'}[m];newSession(id,'project',{kind:k,question,target:10});state().errors=noise;save();render()}})}
