function tool(action,args={}){if(aiBusy&&!['state','report','hint','list'].includes(action))return '本轮是只读证据讨论，不执行实验操作。';try{const s=state();switch(action){case'navigate':return navigate().then(()=> '已打开探究实验室。'+JSON.stringify(snapshot()));case'state':return JSON.stringify(snapshot());case'list':return L.TASKS.map(t=>`${t.id}：${titles[t.id]||t.title}；成果：${deliver[t.id]}`).join('\n');case'open':{const requested=String(args.task||args.id||'N1').trim();const matches=L.TASKS.filter(t=>t.id===requested.toUpperCase()||t.title===requested||titles[t.id]===requested);const id=matches.length===1?matches[0].id:requested.toUpperCase();const mode=args.level==='basic'?'practice':'independent';if(args.level&&!['basic','advanced'].includes(args.level))return '新版提供 basic 引导练习、advanced 独立探究；自主课题请在工作台亲自建立。';if(!L.get(id))return '请选择有效任务编号，例如 N1 或 P3。';return navigate().then(()=>{const old=Object.values(db.sessions).find(s=>s.id===id&&s.v5.mode===mode&&!s.submitted);old?openSession(old.v5.uid):newSession(id,mode);return '已打开 '+id+'。先明确问题，再设计方案。'}).catch(e=>'操作未完成：'+e.message)}case'hint':if(!s)return '请选择一个任务。';return hint(Number(args.level)||1);case'report':if(s&&args.download){if(aiBusy)return '只读讨论不导出文件。';exportReport()}return s?reportText(s):'尚未打开任务。';case'design':case'conclusion':case'exclude':case'submit':return '研究方案、记录取舍和最终结论需要学生在工作台亲自确认。可以读取状态、解释字段或讨论证据。';case'start':return '请在设计方案页亲自确认并记录基准。';case'param':{if(!s)return '尚未打开任务。';if(s.v5.step!==2)return '先进入实验取证步骤。';if(args.method&&s.v5.kind==='compare'){const m=Object.keys(methods).find(k=>k===args.method||methods[k]===args.method);if(!m)return '请选择 N、P 或 S 方法。';stop();s.method=m;touch(s,'文字切换方法');render();return '已切换到'+methods[m]}const requested=args.key||args.param||args.name;const k=L.META[requested]?requested:Object.keys(L.META).find(k=>names[k]===requested||names[k].split(' ')[0]===requested);if(!L.META[k])return '请使用明确参数名称，例如 velocity、radius。';const value=args.factor!=null?s.params[s.method][k]*Number(args.factor):Number(args.value);if(!Number.isFinite(value))return '请输入有效数值或倍数。';L.setParam(s,k,value);touch(s,'文字调节参数');render();return '已调节 '+names[k]+' = '+s.params[s.method][k];}case'capture':if(!s||s.v5.step!==2)return '先进入实验取证步骤。';if(args.release){if(s.method!=='S')return '释放仅适用于落球法。';release();return '已释放小球，请等待轨迹覆盖计时区间后再采集。'}for(const key of ['t1','t2'])if(args[key]!=null){if(!Number.isFinite(Number(args[key])))return '计时区间无效。';s.v5[key]=Number(args[key])}if(args.model)s.v5.selectedModel=args.model;capture();return '已采集第 '+s.rows.length+' 行。';case'analyze':if(!s)return '尚未打开任务。';if(args.axis&&!axes(s).some(a=>a[0]===args.axis))return '此任务不支持该分析坐标。';s.v5.step=3;if(args.axis)s.v5.axis=args.axis;render();analyze();return '已保存分析。'+JSON.stringify(s.analyses.at(-1));default:return '请在新版工作台完成此操作。'}}catch(e){return '操作未完成：'+e.message}}
